import{z as l,x as A,o as n,c as p,q as i,j as o,D as e,d as t,s as B,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"适应性预期与学习","description":"","frontmatter":{"title":"适应性预期与学习","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/adaptive-learning.md","filePath":"econ/adaptive-learning.md","lastUpdated":1791063341000}'),d={name:"econ/adaptive-learning.md"};function m(h,a,C,g,D,_){const r=A("Mermaid");return n(),p("div",null,[a[2]||(a[2]=i('<h1 id="适应性预期与学习" tabindex="-1">适应性预期与学习 <a class="header-anchor" href="#适应性预期与学习" aria-label="Permalink to &quot;适应性预期与学习&quot;">​</a></h1><div class="epigraph"><p>理性预期把信念钉在真实定律上；学习把信念钉在递推估计上，定律与估计互相追，暂时可以偏离 RE 路径。</p><footer>—— Evans and Honkapohja, Learning and Expectations in Macroeconomics, 2001；Marcet and Sargent, Convergence of Least Squares Learning, 1989</footer></div><p><a href="/econ/firm-heterogeneity-investment">上一课</a>仍在理性预期下加总分布。本单元换问题：预期算子本身。本课缺口是<strong>适应性学习</strong>：最小二乘或随机梯度把系数当状态。不重写企业 \\((S,s)\\)，不把粘性信息提前当主模型。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RE：\\(\\mathbb{E}_t\\) 是模型真实条件期望。估计与 BK 都靠它。现实：系数未知，人用过去数据更新。Marcet–Sargent：若学习增益下降，信念可收敛到 RE。Evans–Honkapohja：E-稳定性——若人们相信的定律在学习动态下是吸引子，RE 才「可学习」。常增益学习永远不完全收敛，持续误设可放大冲击。缺口是给「预期」一条可替代 RE 的递推，而不是从零讲最小二乘。</p><p><span class="marginnote">Evans and Honkapohja, Princeton, 2001。Marcet and Sargent, <em>JEDC</em> 1989。Bullard and Mitra 对泰勒规则可学习性。Sargent 的 <em>The Conquest of American Inflation</em>。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>感知定律（PLM）：例如 \\(\\pi_t=\\alpha+\\beta\\pi_{t-1}\\)。真实定律（ALM）由 PLM 代入模型得出。学习：\\(\\theta_t=\\theta_{t-1}+\\gamma_t x_t(\\pi_t-\\theta_{t-1}&#39;x_t)\\)。E-稳定：在 RE 处 ALM 对 PLM 的映射导数稳定。政策：满足 BK 决定性的规则不一定 E-稳定，反之亦然。与校准：学习参数 \\(\\gamma\\) 几乎没有微观钉死，常被用来拟合持续性。</p><p><span class="marginnote">术语翻译：PLM（感知定律）是老百姓心里装的那个简化公式，比如「下期通胀 ≈ 常数 + 0.8 × 本期通胀」；ALM（真实定律）是把这个公式代入经济模型后实际生成数据的定律。学习就是不断用自己的小公式去拟合实际数据，两边互相追。</span></p>',9)),(n(),o(s,null,{default:e(()=>[B(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PLM%5B%22%E6%84%9F%E7%9F%A5%E5%AE%9A%E5%BE%8B%22%5D%20--%3E%20ACT%5B%22%E7%9C%9F%E5%AE%9E%E7%BB%93%E6%9E%9C%22%5D%0A%20%20ACT%20--%3E%20UPD%5B%22%E9%80%92%E6%8E%A8%E6%9B%B4%E6%96%B0%20%CE%B8%22%5D%0A%20%20UPD%20--%3E%20PLM%0A%20%20EST%5B%22E-%E7%A8%B3%E5%AE%9A%22%5D%20--%3E%20RE%5B%22%E6%88%96%E6%94%B6%E6%95%9B%E5%88%B0%20RE%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"太阳黑子均衡的可学习性往往更差，学习有时充当选择装置。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"机制是信念成为额外状态。同一基本面冲击，经错误的 \\(\\beta\\) 预报会自我放大（通胀螺旋、资产价格外推）。常增益把结构变化当可能，适合政策体制转换，也适合制造超额波动。HANK 加上学习：高 MPC 家庭若外推收入，间接效应更猛——可叠加，本课先在代表或简单 NK 里钉装置。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"数字实例：递减增益常取 \\(\\gamma_t=1/t\\)。到第 100 期时新观测的权重只有 \\(1/100=1\\%\\)，旧数据占绝对主导，信念基本冻结；常增益若固定 \\(\\gamma=0.04\\)，则每期最新数据永远占 4% 的权重，误差不会归零，但政策换轨时信念能跟上新体制。")],-1)),a[7]||(a[7]=E("p",null,"与卢卡斯批判：学习模型里「参数」会随政策变，因为样本变。这是批判的一种实现，不是回到适应性预期的老 IS–LM。",-1)),(n(),o(s,null,{default:e(()=>[B(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E5%AD%A6%E4%B9%A0%E5%A2%9E%E7%9B%8A%20%CE%B3%20%E6%80%8E%E4%B9%88%E5%8F%96%22%5D%20--%3E%20DEC%5B%22%E9%80%92%E5%87%8F%E5%A2%9E%E7%9B%8A%3A%20%CE%B3%20%E9%9A%8F%E6%A0%B7%E6%9C%AC%E7%BC%A9%E5%B0%8F%22%5D%0A%20%20G%20--%3E%20CON%5B%22%E5%B8%B8%E5%A2%9E%E7%9B%8A%3A%20%CE%B3%20%E5%9B%BA%E5%AE%9A%E4%B8%8D%E5%BD%92%E9%9B%B6%22%5D%0A%20%20DEC%20--%3E%20CVG%5B%22%E4%BF%A1%E5%BF%B5%E6%94%B6%E6%95%9B%E5%88%B0%20RE%3A%20%E8%AF%AF%E5%B7%AE%E8%B6%8B%E9%9B%B6%22%5D%0A%20%20CON%20--%3E%20LIVE%5B%22%E6%B0%B8%E8%BF%9C%E4%BF%9D%E7%95%99%E8%BF%91%E6%9C%9F%E8%AF%AF%E5%B7%AE%3A%20%E4%BF%A1%E5%BF%B5%E6%8C%81%E7%BB%AD%E6%91%86%E5%8A%A8%22%5D%0A%20%20LIVE%20--%3E%20AMP%5B%22%E5%B0%8F%E5%86%B2%E5%87%BB%E8%A2%AB%E4%BF%A1%E5%BF%B5%E6%94%BE%E5%A4%A7%3A%20%E8%B6%85%E9%A2%9D%E6%B3%A2%E5%8A%A8%2C%20%E9%80%82%E5%90%88%E4%BD%93%E5%88%B6%E8%BD%AC%E6%8D%A2%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=i('<p><span class="marginnote">早期 Cagan、Friedman 的适应性预期是固定滞后权重；现代学习让权重由估计得出。本课用后者。</span></p><p><span class="marginnote">直觉类比：E-稳定性问的是「把 RE 那个点当成谷底，学习这条溪流会不会自己流进去」。若谷底是吸引子，误设的信念会被一次次更新慢慢拽回去；若不是，人再怎么学也停在错误的公式上——所以不是每个 RE 均衡都「学得会」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把粘性信息（Mankiw–Reis）与疏忽（Sims）算作学习——后两课。诊断性预期是认知偏差，也不是最小二乘。调查数据后课才当靶。不估计股市量价。</p><p>后课默认：RE 可被学习动态替换；E-稳定性是额外许可证。下一课：即使知道结构，信息也不是每期都更新。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>学习：PLM 的递推估计；E-稳定性选择可达到的 RE。</li><li>信念是状态，可放大持续性与波动。</li><li>BK 决定性 ≠ 可学习。</li><li>出处：Marcet and Sargent 1989；Evans and Honkapohja 2001。</li></ul>',7))])}const f=l(d,[["render",m]]);export{u as __pageData,f as default};
